INSERT INTO book_catalog (unshelvd_id, title, author, isbn_10, isbn_13, language, publisher, publication_year, genre, cover_url, original_language, country_of_origin, work_id, source, verified)
SELECT e.unshelvd_edition_id, e.title, e.author, e.isbn_10, e.isbn_13, e.language, e.publisher, e.publication_year, e.genre, e.cover_url, e.original_language, e.country_of_origin,
  (SELECT w.id FROM works w WHERE w.unshelvd_id = e.unshelvd_work_id LIMIT 1),
  'manual', true
FROM edition_data e
